const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.box}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fullMoney = value => '฿' + Number(value).toLocaleString('th-TH', {minimumFractionDigits:0, maximumFractionDigits:2});
const billMoney = value => '฿' + Number(value).toLocaleString('th-TH', {minimumFractionDigits:2, maximumFractionDigits:2});
const dayKey = value => new Date(value).toLocaleDateString('en-CA', {timeZone:'Asia/Bangkok'});
const clock = value => new Date(value).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'});
const shortDate = value => new Date(value).toLocaleDateString('th-TH',{day:'numeric',month:'short',timeZone:'Asia/Bangkok'});
const dayDiff = value => Math.round((new Date(dayKey(new Date())) - new Date(dayKey(value)))/86400000);
const when = value => {const d=dayDiff(value);return (d===0?'วันนี้':d===1?'เมื่อวาน':shortDate(value))+' '+clock(value);};
const DEFAULT_CATEGORIES = ['เสื้อใน','กางเกงใน','เสื้อกล้าม','ถุงเท้า'];
const DEFAULT_COLORS = [['ดำ','#0f172a'],['ขาว','#ffffff'],['เนื้อ','#e8c4a8'],['ครีม','#f3e5c8'],['เทา','#9ca3af'],['กรมท่า','#1e2a5a'],['น้ำตาล','#7b4a2b'],['เขียว','#2e7d32'],['ชมพู','#f48fb1'],['ชมพูอ่อน','#f8bbd0'],['บานเย็น','#d81b60'],['แดง','#c62828'],['เลือดหมู','#7b1e2b'],['ม่วง','#7e57c2'],['ฟ้า','#64b5f6'],['เหลือง','#f2c94c']];
