const defaultSettings = () => ({tourDone:false,shop:{name:'',phone:'',address:'',line:'',logo:''},promptpay:{type:'phone',number:'',account:'',showQr:false},nextBill:1,lowStock:{default:3,overrides:{}},categories:[...DEFAULT_CATEGORIES],colors:DEFAULT_COLORS.map(([name,hex])=>({name,hex}))});
function normalize(s){const d=defaultSettings();s.settings={...d,...(s.settings||{})};for(const k of ['shop','promptpay','lowStock'])s.settings[k]={...d[k],...(s.settings[k]||{})};s.settings.lowStock.overrides||={};if(s.shop&&!s.settings.shop.name)s.settings.shop.name=s.shop;delete s.shop;s.customers||=[];s.sales||=[];s.reservations||=[];return s;}
const swatches = () => Object.fromEntries([...state.settings.colors.map(c=>[c.name,c.hex]),['ทั้งหมด','#e2e8f0'],['คละสี','conic-gradient(#f48fb1 0 33%,#64b5f6 0 66%,#e8c4a8 0)']]);
const swatch = name => {const v=String(name).trim();if(!v)return '#ffffff';const map=swatches();return map[v]||map[Object.keys(map).find(k=>v.startsWith(k)||k.startsWith(v))]||'#e2e8f0';};
const categoryIconMap = {'ทั้งหมด':'grid','เสื้อใน':'bra','กางเกงใน':'underwear','เสื้อกล้าม':'shirt','ถุงเท้า':'sock'};
const allCategories = () => ['ทั้งหมด',...state.settings.categories];
const categoryIcon = name => categoryIconMap[name]||'tag';
const limitFor = p => state.settings.lowStock.overrides[p.id] ?? state.settings.lowStock.default;
const shopDetail = () => {const s=state.settings.shop;return [s.address,s.phone&&'โทร '+s.phone].filter(Boolean).join(' · ');};
function bahtText(value){const digits=['','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'],units=['','สิบ','ร้อย','พัน','หมื่น','แสน'];const read=n=>{if(n===0)return '';if(n>=1e6)return read(Math.floor(n/1e6))+'ล้าน'+read(n%1e6);let out='';const str=String(n);for(let i=0;i<str.length;i++){const d=Number(str[i]),pos=str.length-i-1;if(!d)continue;if(pos===1&&d===1)out+='สิบ';else if(pos===1&&d===2)out+='ยี่สิบ';else if(pos===0&&d===1&&str.length>1)out+='เอ็ด';else out+=digits[d]+units[pos];}return out;};const baht=Math.floor(value),satang=Math.round((value-baht)*100);return (baht?read(baht)+'บาท':'')+(satang?read(satang)+'สตางค์':'ถ้วน')||'ศูนย์บาทถ้วน';}
const money = value => '฿' + Number(value).toLocaleString('th-TH', {maximumFractionDigits:2});
const WALK_IN = 'ลูกค้าหน้าร้าน';
const fresh = () => ({version:1,products:[],cart:{},customer:WALK_IN,channel:'หน้าร้าน',discount:0,note:'',sales:[],reservations:[],customers:[],settings:defaultSettings()});
const shopName = () => state.settings.shop.name || 'ร้านของฉัน';
const shopLogo = () => state.settings.shop.logo || 'assets/design-2.png';
let state, storageBroken = false;
try {const saved=JSON.parse(localStorage.getItem(KEY));state=normalize(saved?.version===1 && Array.isArray(saved.products) && saved.cart ? saved : fresh());} catch {state=normalize(fresh());storageBroken=true;}
let page='home', sellOrigin='home', currentId=null, category='ทั้งหมด', search='', sort='name', inStock=false, reservationTab='waiting', lastSale=null, activeReservation=null, form=null, formErrors='', qty=0, quantityId=null, quantityReturn='catalog', toastTimer, searching=false, toastUndo=null, navDir='forward', justIssued=false, receiptOrigin='history', receiptBack='history', bumpId=null, shownRevenue=null, qtyAllocation=[], stockMatrix=[], formBase='', categoryPanel=false, cellEdit=null, sizeDraft=null;
const product = id => state.products.find(p=>p.id===id);
const lines = () => Object.entries(state.cart).flatMap(([id,n])=>product(id)&&n>0?[{...product(id),qty:n}]:[]);
const subtotal = () => lines().reduce((sum,p)=>sum+p.price*p.qty,0);
const total = () => Math.max(0,subtotal()-state.discount);
const packs = items => items.reduce((sum,p)=>sum+p.qty,0);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageBroken=true;toast('บันทึกในเครื่องไม่สำเร็จ โปรดส่งออกข้อมูลก่อนปิดหน้านี้');return false;}}
function toast(text,undo){const el=document.querySelector('#toast');toastUndo=undo||null;el.innerHTML=`<span class="toast-ok">${icon('check')}</span><span class="toast-text">${esc(text)}</span>${undo?'<button type="button" class="toast-undo" data-action="toast-undo">เลิกทำ</button>':''}`;placeToast();el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('visible');toastUndo=null;},undo?6000:4000);}
function placeholder(p,cls=''){return `<div class="placeholder ${cls}">${p?.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:icon('image')}</div>`;}
function buttonIcon(name,action,label,extra=''){return `<button type="button" class="icon-button ${extra}" data-action="${action}" aria-label="${label}">${icon(name)}</button>`;}
function header(title,back='home',actions=''){return `<header class="app-bar">${back?buttonIcon('back','go:'+back,'กลับ'):''}<h1>${title}</h1>${actions?`<div class="header-actions">${actions}</div>`:'<span class="spacer"></span>'}</header>`;}
function footer(html){return `<div class="footer">${html}</div>`;}
function steps(n){return `<ol class="steps">${['เลือกสินค้า','ยืนยันออเดอร์','ออกบิล'].map((s,i)=>`${i+1<n?`<li class="done"><span class="step-number">${icon('check')}</span><span class="visually-hidden">${s}</span></li>`:`<li class="${i+1===n?'active':''}"><span class="step-number">${i+1}</span>${s}</li>`}`).join('')}</ol>`;}
const reduceMotion = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
let transitioning=false;
function withTransition(dir,update){if(!document.startViewTransition||transitioning||document.hidden){update();return;}transitioning=true;document.documentElement.dataset.nav=dir;let ran=false;const once=()=>{if(!ran){ran=true;update();}};setTimeout(()=>{if(!ran){once();transitioning=false;}},400);const t=document.startViewTransition(once);t.updateCallbackDone.catch(()=>{}).finally(()=>{transitioning=false;});t.finished.catch(()=>{}).finally(()=>{if(!transitioning)delete document.documentElement.dataset.nav;});t.ready.catch(()=>{});}
function navigate(next,id){if(dialog.open)dialog.close();if(tablePage[next]&&!returnsToTable(next))tablePage[next]=1;if(next==='catalog'&&typeof TAB_PAGES!=='undefined'&&TAB_PAGES.includes(page))sellOrigin=page;const dir=next==='receipt'&&justIssued&&receiptOrigin==='issued'&&!BILL_BESIDE.matches?'up':navDir;navDir='forward';if(next!=='receipt')justIssued=false;page=next;currentId=id??currentId;search='';searching=false;category='ทั้งหมด';withTransition(dir,()=>{render();app.classList.add('enter');app.scrollTo(0,0);window.scrollTo(0,0);});}
// ---- wide tables: paging applies only from the sidebar breakpoint up; phones keep the continuous list
const tablePage={stock:1,history:1};
const returnsToTable=next=>!search&&category==='ทั้งหมด'&&(next==='stock'&&(page==='detail'||page==='saved')||next==='history'&&page==='receipt');
function paged(list,key,size){const total=list.length;if(!WIDE.matches)return{items:list,key,page:1,pages:1,from:total?1:0,to:total,total};const pages=Math.max(1,Math.ceil(total/size)),at=Math.min(Math.max(1,tablePage[key]),pages),start=(at-1)*size;tablePage[key]=at;return{items:list.slice(start,start+size),key,page:at,pages,from:total?start+1:0,to:Math.min(start+size,total),total};}
function pager(info,summary){if(info.pages<2)return '';const span=DESK.matches?5:3,first=Math.max(1,Math.min(info.page-Math.floor(span/2),info.pages-span+1)),nums=[];for(let n=first;n<=Math.min(info.pages,first+span-1);n++)nums.push(n);const step=(n,name,label,off)=>`<button type="button" data-action="page:${info.key}:${n}" aria-label="${label}" ${off?'disabled':''}>${icon(name)}</button>`;return `<nav class="pager" aria-label="เลขหน้า"><span class="pager-sum">${summary(info)}</span><div class="pager-nums">${step(info.page-1,'back','หน้าก่อนหน้า',info.page<2)}${nums.map(n=>`<button type="button" data-action="page:${info.key}:${n}" ${n===info.page?'aria-current="page"':''}>${n}</button>`).join('')}${step(info.page+1,'arrow','หน้าถัดไป',info.page>=info.pages)}</div></nav>`;}
function searchInline(label){return `<label class="search-field search-inline">${icon('search')}<input id="search" type="search" value="${esc(search)}" placeholder="${label}" aria-label="${label}" autocomplete="off"></label>`;}
function categoryStrip(kind){return `<nav class="cat-strip ${kind}" aria-label="หมวดสินค้า">${allCategories().map(c=>`<button type="button" class="${category===c?'active':''}" data-action="category:${esc(c)}" aria-pressed="${category===c}">${icon(categoryIcon(c))}<span>${esc(c)}</span></button>`).join('')}</nav>`;}
function categoryChips(){return categoryStrip('in-flow');}
function refreshResults(){const r=document.querySelector('#results'),c=document.querySelector('#result-count');if(r)r.innerHTML=page==='catalog'?gridView():page==='history'?historyRows():stockResults();if(c)c.textContent=search?`พบ ${filtered().length} รุ่น`:'';}
const views={};const pageTitles={home:'โฮม',stock:'สต็อกสินค้า',catalog:'ขาย',checkout:'ยืนยันออเดอร์',detail:'รายละเอียดสินค้า',add:'เพิ่มสต็อก',receipt:'บิลเงินสด',history:'ประวัติการขาย',reservations:'รายการจอง'};
function render(){Object.assign(views,{home:homeView,stock:stockView,catalog:catalogView,detail:detailView,checkout:checkoutView,receipt:receiptView,add:formView,saved:savedView,reservations:reservationsView,reservation:reservationView,history:historyView},window.extraViews||{});app.classList.remove('enter');app.dataset.page=page;document.body.dataset.page=page;app.innerHTML=(views[page]||homeView)();const actionBar=document.querySelector('#action-bar');actionBar.replaceChildren();const footerElement=app.querySelector('.footer');if(footerElement)actionBar.append(footerElement);document.title=(pageTitles[page]||'Khonnai')+(state.settings.shop.name?' — '+state.settings.shop.name:'');if(typeof renderNav==='function')renderNav();placeToast();if(page==='home')countRevenue();}
function placeToast(){const bar=document.querySelector('#action-bar .footer');document.querySelector('#toast').style.bottom=bar?`${bar.offsetHeight+16}px`:document.body.dataset.nav==='tabs'?'calc(max(12px,env(safe-area-inset-bottom)) + 114px)':'16px';}
function countRevenue(){const el=app.querySelector('.revenue strong');if(!el)return;const to=Number(el.dataset.revenue),from=shownRevenue;shownRevenue=to;if(from===null||from===to||reduceMotion()||document.hidden)return;const start=performance.now(),duration=700,whole=Number.isInteger(from)&&Number.isInteger(to);el.textContent=fullMoney(from);const step=now=>{const k=Math.min(1,Math.max(0,(now-start)/duration)),eased=1-Math.pow(1-k,4),shown=from+(to-from)*eased;el.textContent=fullMoney(whole?Math.round(shown):shown);if(k<1&&el.isConnected)requestAnimationFrame(step);};requestAnimationFrame(step);}
function restockOptions(){return state.products.filter(p=>!p.hidden).flatMap(p=>p.values?p.colors.flatMap((color,i)=>p.sizes.map((size,j)=>({p,size,color,stock:p.values[i][j],limit:limitFor(p)}))):[]).filter(o=>o.stock<o.limit).sort((a,b)=>a.stock-b.stock);}
